namespace Harborline.Foundation.NotificationDelivery;

/// <summary>
/// A closed transport identifier. Release 1 admits only the on-node inbox
/// (<c>notification-delivery-ck-1</c>).
/// </summary>
public readonly record struct DeliveryChannelKey
{
    private DeliveryChannelKey(string value) => Value = value;

    /// <summary>The recipient's on-node inbox transport.</summary>
    public static DeliveryChannelKey Inbox { get; } = new("inbox");

    /// <summary>The stable transport name.</summary>
    public string Value { get; }

    /// <inheritdoc />
    public override string ToString() => Value ?? string.Empty;
}

/// <summary>The amount of a rendered notification a transport is permitted to carry.</summary>
public enum ChannelContentClass
{
    /// <summary>The on-node transport carries the complete rendered notification.</summary>
    OnNodeFull = 0,
    /// <summary>An off-node transport carries its tier, definition title, subject display name and link only.</summary>
    LinkOnly = 1,
}

/// <summary>
/// Code-registered transport capabilities. Secret requirements and retry profiles are names rather
/// than values, so a binding can never become a credential store.
/// </summary>
public sealed record DeliveryChannel(
    DeliveryChannelKey Key,
    IReadOnlySet<string> RequiredSecretReferenceNames,
    IReadOnlySet<string> AllowedRetryProfiles,
    ChannelContentClass ContentClass);

/// <summary>
/// Tenant configuration for a registered channel. It can identify secrets held by the tenant, but
/// never stores their values (<c>notification-delivery-ck-2</c>).
/// </summary>
public sealed record ChannelBinding
{
    /// <summary>
    /// Creates a binding after ensuring its channel exists and every supplied secret reference is
    /// declared by that channel.
    /// </summary>
    public ChannelBinding(
        string tenant,
        DeliveryChannelKey channel,
        bool enabled,
        string? senderIdentity,
        IReadOnlyList<string> secretReferenceIds)
    {
        ArgumentNullException.ThrowIfNull(secretReferenceIds);
        var registered = DeliveryChannels.Require(channel);
        if (secretReferenceIds.Count != 0 && registered.RequiredSecretReferenceNames.Count == 0)
        {
            throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.SecretReferenceNotAllowed,
                $"Channel '{channel}' declares no secret references.");
        }

        Tenant = tenant;
        Channel = channel;
        Enabled = enabled;
        SenderIdentity = senderIdentity;
        SecretReferenceIds = secretReferenceIds.ToArray();
    }

    /// <summary>The tenant that owns this non-portable channel configuration.</summary>
    public string Tenant { get; }

    /// <summary>The registered transport this configuration enables or disables.</summary>
    public DeliveryChannelKey Channel { get; }

    /// <summary>Whether the tenant admits this transport for routing.</summary>
    public bool Enabled { get; }

    /// <summary>The transport's configured sender identity, when that transport uses one.</summary>
    public string? SenderIdentity { get; }

    /// <summary>Tenant-held secret reference identifiers; this collection never contains secret values.</summary>
    public IReadOnlyList<string> SecretReferenceIds { get; }
}

/// <summary>Raised when a notification-delivery boundary refuses invalid channel configuration.</summary>
public sealed class NotificationDeliveryRefusedException : InvalidOperationException
{
    /// <summary>Creates a refusal with a stable machine-readable code and an operator-readable explanation.</summary>
    public NotificationDeliveryRefusedException(string code, string message)
        : base(message) => Code = code;

    /// <summary>The stable refusal code.</summary>
    public string Code { get; }
}

/// <summary>Stable refusal codes emitted by the channels slice.</summary>
public static class NotificationDeliveryRefusals
{
    /// <summary>The caller named a transport that this release does not register.</summary>
    public const string ChannelUnknown = "notification_delivery.channel_unknown";

    /// <summary>The binding supplied secret references to a transport that declares none.</summary>
    public const string SecretReferenceNotAllowed = "notification_delivery.secret_reference_not_allowed";

    /// <summary>The caller supplied no usable value for an inbox-entry field that the inbox must render.</summary>
    public const string InboxEntryInvalid = "notification_delivery.inbox_entry_invalid";

    /// <summary>The caller tried to update an entry that does not belong to the current person's inbox.</summary>
    public const string InboxEntryUnknown = "notification_delivery.inbox_entry_unknown";
}

/// <summary>The code registry for delivery transports; a new transport registers here, not a second delivery path.</summary>
public static class DeliveryChannels
{
    private static readonly DeliveryChannel Inbox = new(
        DeliveryChannelKey.Inbox,
        new HashSet<string>(StringComparer.Ordinal),
        new HashSet<string>(StringComparer.Ordinal),
        ChannelContentClass.OnNodeFull);

    /// <summary>The mandatory privacy class with which a future off-node channel must begin.</summary>
    public static ChannelContentClass ExternalDefaultContentClass => ChannelContentClass.LinkOnly;

    /// <summary>Returns the registered channel or refuses a channel key unavailable in this release.</summary>
    public static DeliveryChannel Require(DeliveryChannelKey key) =>
        key == DeliveryChannelKey.Inbox
            ? Inbox
            : throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.ChannelUnknown,
                $"Channel '{key}' is not registered.");
}

namespace Harborline.Foundation.NotificationDelivery;

/// <summary>The per-person state of an inbox entry, shared by every device for that person.</summary>
public enum InboxReadState
{
    /// <summary>The recipient has not yet read the entry.</summary>
    Unread = 0,
    /// <summary>The recipient has read the entry.</summary>
    Read = 1,
    /// <summary>The recipient has removed the entry from their active inbox.</summary>
    Dismissed = 2,
}

/// <summary>
/// One durable, on-node notification-centre item. Its rendered content is intentionally retained
/// here rather than projected to an external channel (<c>notification-delivery-ck-10</c>).
/// </summary>
public sealed record InboxEntry(
    Guid Id,
    string Tenant,
    string Recipient,
    string Tier,
    string Title,
    string RenderedContent,
    string SubjectDisplayName,
    string SubjectLink,
    bool AnswerOwed,
    DateTimeOffset CreatedAt,
    InboxReadState ReadState);

/// <summary>The caller-provided content for one inbox write.</summary>
public sealed record WriteInboxEntry(
    string Tenant,
    string Recipient,
    string Tier,
    string Title,
    string RenderedContent,
    string SubjectDisplayName,
    string SubjectLink,
    bool AnswerOwed);

/// <summary>Tenant- and recipient-scoped inbox persistence and read-state operations.</summary>
public interface IInboxStore
{
    /// <summary>Appends the delivered entry before it becomes visible to the recipient.</summary>
    Task<InboxEntry> AppendAsync(InboxEntry entry, CancellationToken cancellationToken = default);

    /// <summary>Lists one recipient's entries newest first for the notification-centre surface.</summary>
    Task<IReadOnlyList<InboxEntry>> ListAsync(string tenant, string recipient, CancellationToken cancellationToken = default);

    /// <summary>Counts unread entries for the same recipient the notification centre displays.</summary>
    Task<int> UnreadCountAsync(string tenant, string recipient, CancellationToken cancellationToken = default);

    /// <summary>Marks one entry read for every session belonging to its recipient.</summary>
    Task MarkReadAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default);

    /// <summary>Marks every unread entry read for the recipient's notification centre.</summary>
    Task MarkAllReadAsync(string tenant, string recipient, CancellationToken cancellationToken = default);
}

/// <summary>In-process atomic inbox persistence suitable for development composition and focused tests.</summary>
public sealed class InMemoryInboxStore : IInboxStore
{
    private readonly object _gate = new();
    private readonly Dictionary<Guid, InboxEntry> _entries = [];

    /// <inheritdoc />
    public Task<InboxEntry> AppendAsync(InboxEntry entry, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entry);
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            _entries.Add(entry.Id, entry);
            return Task.FromResult(entry);
        }
    }

    /// <inheritdoc />
    public Task<IReadOnlyList<InboxEntry>> ListAsync(string tenant, string recipient, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            IReadOnlyList<InboxEntry> entries = _entries.Values
                .Where(entry => entry.Tenant == tenant && entry.Recipient == recipient)
                .OrderByDescending(entry => entry.CreatedAt)
                .ThenBy(entry => entry.Id)
                .ToArray();
            return Task.FromResult(entries);
        }
    }

    /// <inheritdoc />
    public Task<int> UnreadCountAsync(string tenant, string recipient, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            return Task.FromResult(_entries.Values.Count(entry => entry.Tenant == tenant
                && entry.Recipient == recipient
                && entry.ReadState == InboxReadState.Unread));
        }
    }

    /// <inheritdoc />
    public Task MarkReadAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            if (!_entries.TryGetValue(entryId, out var entry) || entry.Tenant != tenant || entry.Recipient != recipient)
            {
                throw new NotificationDeliveryRefusedException(
                    NotificationDeliveryRefusals.InboxEntryUnknown,
                    $"Inbox entry '{entryId}' is not in this recipient's inbox.");
            }

            _entries[entryId] = entry with { ReadState = InboxReadState.Read };
            return Task.CompletedTask;
        }
    }

    /// <inheritdoc />
    public Task MarkAllReadAsync(string tenant, string recipient, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            foreach (var entry in _entries.Values.Where(entry => entry.Tenant == tenant
                && entry.Recipient == recipient
                && entry.ReadState == InboxReadState.Unread).ToArray())
            {
                _entries[entry.Id] = entry with { ReadState = InboxReadState.Read };
            }

            return Task.CompletedTask;
        }
    }
}

/// <summary>The in-app delivery channel that writes complete rendered content to the person's on-node inbox.</summary>
public sealed class InboxChannel
{
    private readonly IInboxStore _store;
    private readonly TimeProvider _clock;

    /// <summary>Creates the channel with its durable inbox boundary and the authoritative time source.</summary>
    public InboxChannel(IInboxStore store, TimeProvider clock)
    {
        _store = store ?? throw new ArgumentNullException(nameof(store));
        _clock = clock ?? throw new ArgumentNullException(nameof(clock));
    }

    /// <summary>Writes one unread inbox entry with the full rendered content and returns the committed item.</summary>
    public async Task<InboxEntry> WriteAsync(WriteInboxEntry request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        RequireContent(request.Tenant, nameof(request.Tenant));
        RequireContent(request.Recipient, nameof(request.Recipient));
        RequireContent(request.Tier, nameof(request.Tier));
        RequireContent(request.Title, nameof(request.Title));
        RequireContent(request.RenderedContent, nameof(request.RenderedContent));
        RequireContent(request.SubjectDisplayName, nameof(request.SubjectDisplayName));
        RequireContent(request.SubjectLink, nameof(request.SubjectLink));
        var entry = new InboxEntry(
            Guid.NewGuid(),
            request.Tenant,
            request.Recipient,
            request.Tier,
            request.Title,
            request.RenderedContent,
            request.SubjectDisplayName,
            request.SubjectLink,
            request.AnswerOwed,
            _clock.GetUtcNow(),
            InboxReadState.Unread);
        return await _store.AppendAsync(entry, cancellationToken).ConfigureAwait(false);
    }

    private static void RequireContent(string value, string parameterName)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.InboxEntryInvalid,
                $"Inbox entry field '{parameterName}' is required.");
        }
    }
}

using Harborline.Foundation.NotificationDelivery;
using Xunit;

namespace Harborline.Foundation.NotificationDelivery.Tests;

public sealed class DeliveryChannelBoundaryTests
{
    // DES-0055 notification-delivery-ck-1: the R1 transport key is literally "inbox".
    [Fact]
    public void Notification_delivery_ck_1_inbox_key_renders_its_stable_name_and_default_renders_empty()
    {
        Assert.Equal("inbox", DeliveryChannelKey.Inbox.Value);
        Assert.Equal("inbox", DeliveryChannelKey.Inbox.ToString());
        Assert.Null(default(DeliveryChannelKey).Value);
        Assert.Equal(string.Empty, default(DeliveryChannelKey).ToString());
    }

    [Fact]
    public void Notification_delivery_ck_1_unknown_channel_refuses_with_a_code_and_operator_explanation()
    {
        var exception = Assert.Throws<NotificationDeliveryRefusedException>(() => DeliveryChannels.Require(default));

        Assert.Equal("notification_delivery.channel_unknown", exception.Code);
        Assert.Equal("Channel '' is not registered.", exception.Message);
    }

    // DES-0055 notification-delivery-ck-2: empty secret references are valid for an inbox binding.
    [Theory]
    [InlineData(true, "notification-sender")]
    [InlineData(false, null)]
    public void Notification_delivery_ck_2_empty_binding_preserves_tenant_channel_enablement_and_sender(
        bool enabled, string? senderIdentity)
    {
        var binding = new ChannelBinding("tenant-a", DeliveryChannelKey.Inbox, enabled, senderIdentity, []);

        Assert.Equal("tenant-a", binding.Tenant);
        Assert.Equal("inbox", binding.Channel.Value);
        Assert.Equal(enabled, binding.Enabled);
        Assert.Equal(senderIdentity, binding.SenderIdentity);
        Assert.Empty(binding.SecretReferenceIds);
    }

    [Fact]
    public void Notification_delivery_ck_2_binding_copies_references_instead_of_retaining_the_callers_list()
    {
        var references = new List<string>();
        var binding = new ChannelBinding("tenant-a", DeliveryChannelKey.Inbox, true, null, references);

        references.Add("secret://smtp/password");

        Assert.Empty(binding.SecretReferenceIds);
    }

    [Fact]
    public void Notification_delivery_ck_2_null_reference_collection_is_refused_before_binding()
    {
        var exception = Assert.Throws<ArgumentNullException>(() => new ChannelBinding(
            "tenant-a", DeliveryChannelKey.Inbox, true, null, null!));

        Assert.Equal("secretReferenceIds", exception.ParamName);
    }

    [Fact]
    public void Notification_delivery_ck_2_binding_an_unknown_channel_refuses_even_without_secrets()
    {
        var exception = Assert.Throws<NotificationDeliveryRefusedException>(() => new ChannelBinding(
            "tenant-a", default, true, null, []));

        Assert.Equal("notification_delivery.channel_unknown", exception.Code);
        Assert.Equal("Channel '' is not registered.", exception.Message);
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void Notification_delivery_ck_2_inbox_secrets_refuse_even_when_the_binding_is_disabled(bool enabled)
    {
        var exception = Assert.Throws<NotificationDeliveryRefusedException>(() => new ChannelBinding(
            "tenant-a", DeliveryChannelKey.Inbox, enabled, null, ["secret://smtp/password"]));

        Assert.Equal("notification_delivery.secret_reference_not_allowed", exception.Code);
        Assert.Equal("Channel 'inbox' declares no secret references.", exception.Message);
    }
}

using Harborline.Foundation.NotificationDelivery;
using Xunit;

namespace Harborline.Foundation.NotificationDelivery.Tests;

public sealed class InboxChannelTests
{
    [Fact]
    public async Task Write_then_read_and_mark_read_share_one_principal_inbox()
    {
        var inbox = new InMemoryInboxStore();
        const string recipient = "principal-a";
        var channel = new InboxChannel(inbox, TimeProvider.System);
        var written = await channel.WriteAsync(new WriteInboxEntry(
            "tenant-a",
            recipient,
            "decision",
            "Approval required",
            "The full rendered message stays on the node.",
            "Record 17",
            "/records/17",
            true));

        var beforeRead = await inbox.ListAsync("tenant-a", recipient);
        Assert.Single(beforeRead);
        Assert.Equal("The full rendered message stays on the node.", beforeRead[0].RenderedContent);
        Assert.Equal(InboxReadState.Unread, beforeRead[0].ReadState);
        Assert.Equal(1, await inbox.UnreadCountAsync("tenant-a", recipient));

        await inbox.MarkReadAsync("tenant-a", recipient, written.Id);

        Assert.Equal(0, await inbox.UnreadCountAsync("tenant-a", recipient));
        Assert.Equal(InboxReadState.Read, (await inbox.ListAsync("tenant-a", recipient))[0].ReadState);
    }

    [Fact]
    public void Inbox_is_the_only_registered_initial_channel_and_needs_no_secret_or_retry_profile()
    {
        var channel = DeliveryChannels.Require(DeliveryChannelKey.Inbox);

        Assert.Equal(DeliveryChannelKey.Inbox, channel.Key);
        Assert.Empty(channel.RequiredSecretReferenceNames);
        Assert.Empty(channel.AllowedRetryProfiles);
        Assert.Equal(ChannelContentClass.OnNodeFull, channel.ContentClass);
        Assert.Equal(ChannelContentClass.LinkOnly, DeliveryChannels.ExternalDefaultContentClass);
        Assert.Throws<NotificationDeliveryRefusedException>(() => DeliveryChannels.Require(default));
    }

    [Fact]
    public void Inbox_binding_refuses_secret_references_because_the_inbox_needs_none()
    {
        var exception = Assert.Throws<NotificationDeliveryRefusedException>(() => new ChannelBinding(
            "tenant-a",
            DeliveryChannelKey.Inbox,
            enabled: true,
            senderIdentity: null,
            secretReferenceIds: ["secret://smtp/password"]));

        Assert.Equal("notification_delivery.secret_reference_not_allowed", exception.Code);
    }

    [Fact]
    public async Task Inbox_refuses_an_entry_missing_rendered_content()
    {
        var channel = new InboxChannel(new InMemoryInboxStore(), TimeProvider.System);

        var exception = await Assert.ThrowsAsync<NotificationDeliveryRefusedException>(() => channel.WriteAsync(new WriteInboxEntry(
            "tenant-a",
            "principal-a",
            "information",
            "Update",
            " ",
            "Record 17",
            "/records/17",
            false)));

        Assert.Equal("notification_delivery.inbox_entry_invalid", exception.Code);
    }

    [Theory]
    [InlineData(" ", "principal-a")]
    [InlineData("tenant-a", " ")]
    public async Task Inbox_refuses_and_does_not_persist_an_entry_with_a_blank_tenant_or_recipient(string tenant, string recipient)
    {
        var inbox = new InMemoryInboxStore();
        var channel = new InboxChannel(inbox, TimeProvider.System);

        var exception = await Assert.ThrowsAsync<NotificationDeliveryRefusedException>(() => channel.WriteAsync(new WriteInboxEntry(
            tenant,
            recipient,
            "information",
            "Update",
            "The full rendered message stays on the node.",
            "Record 17",
            "/records/17",
            false)));

        Assert.Equal("notification_delivery.inbox_entry_invalid", exception.Code);
        Assert.Empty(await inbox.ListAsync(tenant, recipient));
    }
}

using Harborline.Foundation.NotificationDelivery;
using Xunit;

namespace Harborline.Foundation.NotificationDelivery.Tests;

public sealed class InboxStoreBoundaryTests
{
    private static readonly DateTimeOffset Epoch = new(2026, 9, 30, 12, 0, 0, TimeSpan.Zero);

    // DES-0055 notification-delivery-ck-10 and notification-delivery-cc-2: durable tenant data, per person.
    [Fact]
    public async Task Notification_delivery_cc_2_list_isolates_both_tenant_and_recipient()
    {
        var (store, entries) = await MixedInboxAsync();

        var listed = await store.ListAsync("tenant-a", "principal-a");

        Assert.Equal(new[] { Id(4), Id(3), Id(2), Id(1) }, listed.Select(entry => entry.Id));
        Assert.Equal(entries.Where(entry => entry.Id == Id(4) || entry.Id == Id(3) || entry.Id == Id(2) || entry.Id == Id(1))
            .Reverse(), listed);
        Assert.Empty(await store.ListAsync("tenant-missing", "principal-a"));
        Assert.Empty(await store.ListAsync("tenant-a", "principal-missing"));
    }

    [Fact]
    public async Task Notification_delivery_cc_2_unread_count_excludes_read_dismissed_and_other_inboxes()
    {
        var (store, _) = await MixedInboxAsync();

        Assert.Equal(2, await store.UnreadCountAsync("tenant-a", "principal-a"));
        Assert.Equal(1, await store.UnreadCountAsync("tenant-a", "principal-b"));
        Assert.Equal(1, await store.UnreadCountAsync("tenant-b", "principal-a"));
        Assert.Equal(0, await store.UnreadCountAsync("tenant-missing", "principal-a"));
        Assert.Equal(0, await store.UnreadCountAsync("tenant-a", "principal-missing"));
    }

    [Fact]
    public async Task Notification_delivery_cc_2_entries_are_newest_first_even_when_appended_out_of_order()
    {
        var store = new InMemoryInboxStore();
        await store.AppendAsync(Entry(1, "tenant-a", "principal-a", InboxReadState.Unread, Epoch));
        await store.AppendAsync(Entry(3, "tenant-a", "principal-a", InboxReadState.Read, Epoch.AddMinutes(2)));
        await store.AppendAsync(Entry(2, "tenant-a", "principal-a", InboxReadState.Unread, Epoch.AddMinutes(1)));

        Assert.Equal(new[] { Id(3), Id(2), Id(1) }, (await store.ListAsync("tenant-a", "principal-a")).Select(entry => entry.Id));
    }

    // Local compatibility regression: DES-0055 cc-2 specifies newest-first, but leaves ties unspecified.
    [Fact]
    public async Task Inbox_equal_timestamp_entries_use_ascending_id_as_a_repeatable_tiebreak()
    {
        var store = new InMemoryInboxStore();
        await store.AppendAsync(Entry(3, "tenant-a", "principal-a", InboxReadState.Unread, Epoch));
        await store.AppendAsync(Entry(1, "tenant-a", "principal-a", InboxReadState.Unread, Epoch));
        await store.AppendAsync(Entry(2, "tenant-a", "principal-a", InboxReadState.Unread, Epoch));

        Assert.Equal(new[] { Id(1), Id(2), Id(3) }, (await store.ListAsync("tenant-a", "principal-a")).Select(entry => entry.Id));
    }

    // DES-0055 notification-delivery-ck-7: reading one item changes only that person's item.
    [Fact]
    public async Task Notification_delivery_ck_7_mark_read_changes_only_the_named_entry_and_is_idempotent()
    {
        var (store, entries) = await MixedInboxAsync();

        await store.MarkReadAsync("tenant-a", "principal-a", Id(1));
        await store.MarkReadAsync("tenant-a", "principal-a", Id(1));

        Assert.Equal(1, await store.UnreadCountAsync("tenant-a", "principal-a"));
        foreach (var original in entries)
        {
            var actual = Assert.Single((await store.ListAsync(original.Tenant, original.Recipient)), entry => entry.Id == original.Id);
            Assert.Equal(original.Id == Id(1) ? original with { ReadState = InboxReadState.Read } : original, actual);
        }
    }

    [Theory]
    [InlineData("tenant-b", "principal-a", 1)]
    [InlineData("tenant-a", "principal-b", 1)]
    [InlineData("tenant-b", "principal-b", 1)]
    [InlineData("Tenant-a", "principal-a", 1)]
    [InlineData("tenant-a", "Principal-a", 1)]
    [InlineData("tenant-a", "principal-a", 99)]
    public async Task Notification_delivery_ck_7_wrong_scope_or_missing_entry_refuses_without_changing_any_inbox(
        string tenant, string recipient, int entryNumber)
    {
        var (store, entries) = await MixedInboxAsync();

        var exception = await Assert.ThrowsAsync<NotificationDeliveryRefusedException>(
            () => store.MarkReadAsync(tenant, recipient, Id(entryNumber)));

        Assert.Equal("notification_delivery.inbox_entry_unknown", exception.Code);
        Assert.Equal($"Inbox entry '{Id(entryNumber)}' is not in this recipient's inbox.", exception.Message);
        await AssertUnchangedAsync(store, entries);
    }

    [Fact]
    public async Task Notification_delivery_ck_7_mark_all_read_changes_only_scoped_unread_entries_and_is_idempotent()
    {
        // IInboxStore.MarkAllReadAsync promises unread-only updates; dismissed entries stay dismissed.
        var (store, entries) = await MixedInboxAsync();

        await store.MarkAllReadAsync("tenant-a", "principal-a");
        await store.MarkAllReadAsync("tenant-a", "principal-a");

        Assert.Equal(0, await store.UnreadCountAsync("tenant-a", "principal-a"));
        Assert.Equal(1, await store.UnreadCountAsync("tenant-a", "principal-b"));
        Assert.Equal(1, await store.UnreadCountAsync("tenant-b", "principal-a"));
        foreach (var original in entries)
        {
            var actual = Assert.Single((await store.ListAsync(original.Tenant, original.Recipient)), entry => entry.Id == original.Id);
            Assert.Equal(original.Id == Id(1) || original.Id == Id(2)
                ? original with { ReadState = InboxReadState.Read }
                : original, actual);
        }
    }

    [Fact]
    public async Task Notification_delivery_ck_7_mark_all_read_of_missing_scope_leaves_all_inboxes_unchanged()
    {
        var (store, entries) = await MixedInboxAsync();

        await store.MarkAllReadAsync("tenant-missing", "principal-a");
        await store.MarkAllReadAsync("tenant-a", "principal-missing");

        await AssertUnchangedAsync(store, entries);
    }

    [Fact]
    public async Task Notification_delivery_ck_10_append_rejects_null_and_duplicate_ids_without_losing_the_first_entry()
    {
        var store = new InMemoryInboxStore();
        var nullRefusal = await Assert.ThrowsAsync<ArgumentNullException>(() => store.AppendAsync(null!));
        Assert.Equal("entry", nullRefusal.ParamName);

        var first = Entry(1, "tenant-a", "principal-a", InboxReadState.Unread, Epoch);
        Assert.Equal(first, await store.AppendAsync(first));
        await Assert.ThrowsAsync<ArgumentException>(() => store.AppendAsync(first with { Title = "Replacement must refuse" }));

        Assert.Equal(first, Assert.Single(await store.ListAsync("tenant-a", "principal-a")));
    }

    [Theory]
    [InlineData("append")]
    [InlineData("list")]
    [InlineData("unread-count")]
    [InlineData("mark-read")]
    [InlineData("mark-all-read")]
    public async Task Inbox_cancelled_operation_throws_without_changing_any_inbox(string operation)
    {
        var (store, entries) = await MixedInboxAsync();
        using var cancelled = new CancellationTokenSource();
        cancelled.Cancel();

        var exception = await Assert.ThrowsAsync<OperationCanceledException>(() => operation switch
        {
            "append" => store.AppendAsync(Entry(99, "tenant-a", "principal-a", InboxReadState.Unread, Epoch), cancelled.Token),
            "list" => store.ListAsync("tenant-a", "principal-a", cancelled.Token),
            "unread-count" => store.UnreadCountAsync("tenant-a", "principal-a", cancelled.Token),
            "mark-read" => store.MarkReadAsync("tenant-a", "principal-a", Id(1), cancelled.Token),
            "mark-all-read" => store.MarkAllReadAsync("tenant-a", "principal-a", cancelled.Token),
            _ => throw new ArgumentOutOfRangeException(nameof(operation)),
        });

        Assert.Equal(cancelled.Token, exception.CancellationToken);
        await AssertUnchangedAsync(store, entries);
    }

    private static async Task AssertUnchangedAsync(InMemoryInboxStore store, IReadOnlyList<InboxEntry> entries)
    {
        foreach (var scope in entries.Select(entry => (entry.Tenant, entry.Recipient)).Distinct())
        {
            var expected = entries.Where(entry => entry.Tenant == scope.Tenant && entry.Recipient == scope.Recipient);
            var actual = await store.ListAsync(scope.Tenant, scope.Recipient);
            Assert.Equal(expected.OrderByDescending(entry => entry.CreatedAt).ThenBy(entry => entry.Id), actual);
        }
    }

    private static async Task<(InMemoryInboxStore Store, InboxEntry[] Entries)> MixedInboxAsync()
    {
        var entries = new[]
        {
            Entry(1, "tenant-a", "principal-a", InboxReadState.Unread, Epoch),
            Entry(2, "tenant-a", "principal-a", InboxReadState.Unread, Epoch.AddMinutes(1)),
            Entry(3, "tenant-a", "principal-a", InboxReadState.Read, Epoch.AddMinutes(2)),
            Entry(4, "tenant-a", "principal-a", InboxReadState.Dismissed, Epoch.AddMinutes(3)),
            Entry(5, "tenant-a", "principal-b", InboxReadState.Unread, Epoch.AddMinutes(4)),
            Entry(6, "tenant-b", "principal-a", InboxReadState.Unread, Epoch.AddMinutes(5)),
            Entry(7, "tenant-b", "principal-b", InboxReadState.Unread, Epoch.AddMinutes(6)),
            Entry(8, "Tenant-a", "principal-a", InboxReadState.Unread, Epoch.AddMinutes(7)),
            Entry(9, "tenant-a", "Principal-a", InboxReadState.Unread, Epoch.AddMinutes(8)),
        };
        var store = new InMemoryInboxStore();
        foreach (var entry in entries) await store.AppendAsync(entry);
        return (store, entries);
    }

    private static InboxEntry Entry(int number, string tenant, string recipient, InboxReadState state, DateTimeOffset createdAt) =>
        new(Id(number), tenant, recipient, "information", $"Entry {number}", $"Full content {number}",
            $"Record {number}", $"/records/{number}", false, createdAt, state);

    private static Guid Id(int number) => Guid.Parse(FormattableString.Invariant($"00000000-0000-0000-0000-{number:000000000000}"));
}

using Harborline.Foundation.NotificationDelivery;
using Xunit;

namespace Harborline.Foundation.NotificationDelivery.Tests;

public sealed class InboxWriteBoundaryTests
{
    private static readonly DateTimeOffset WrittenAt = new(2026, 9, 30, 12, 34, 56, TimeSpan.Zero);

    public static IEnumerable<object[]> InvalidRequiredContent()
    {
        foreach (var field in new[] { "Tenant", "Recipient", "Tier", "Title", "RenderedContent", "SubjectDisplayName", "SubjectLink" })
        {
            foreach (var value in new string?[] { null, string.Empty, " \t\r\n " })
            {
                yield return new object[] { field, value! };
            }
        }
    }

    // DES-0055 notification-delivery-ck-10 defines the inbox content role. Required fields and
    // exact diagnostic wording below pin the local API compatibility contract.
    // The recording store is independent of InMemoryInboxStore's validation and query behavior.
    [Theory]
    [MemberData(nameof(InvalidRequiredContent))]
    public async Task Notification_delivery_ck_10_missing_required_content_refuses_before_any_append(string field, string? value)
    {
        var store = new RecordingInboxStore();
        var channel = new InboxChannel(store, new FixedClock());
        var valid = Request(answerOwed: false);
        var invalid = field switch
        {
            "Tenant" => valid with { Tenant = value! },
            "Recipient" => valid with { Recipient = value! },
            "Tier" => valid with { Tier = value! },
            "Title" => valid with { Title = value! },
            "RenderedContent" => valid with { RenderedContent = value! },
            "SubjectDisplayName" => valid with { SubjectDisplayName = value! },
            "SubjectLink" => valid with { SubjectLink = value! },
            _ => throw new ArgumentOutOfRangeException(nameof(field)),
        };

        var exception = await Assert.ThrowsAsync<NotificationDeliveryRefusedException>(() => channel.WriteAsync(invalid));

        Assert.Equal("notification_delivery.inbox_entry_invalid", exception.Code);
        Assert.Equal($"Inbox entry field '{field}' is required.", exception.Message);
        Assert.Equal(0, store.AppendCalls);
        Assert.Null(store.Appended);
    }

    [Fact]
    public async Task Notification_delivery_ck_10_null_request_refuses_before_any_append()
    {
        var store = new RecordingInboxStore();
        var channel = new InboxChannel(store, new FixedClock());

        var exception = await Assert.ThrowsAsync<ArgumentNullException>(() => channel.WriteAsync(null!));

        Assert.Equal("request", exception.ParamName);
        Assert.Equal(0, store.AppendCalls);
        Assert.Null(store.Appended);
    }

    // DES-0055 notification-delivery-ck-7 and ck-10: full on-node content, unread state, answer owed and time.
    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public async Task Notification_delivery_ck_10_write_preserves_all_content_and_stamps_a_new_unread_entry(bool answerOwed)
    {
        var store = new RecordingInboxStore();
        var channel = new InboxChannel(store, new FixedClock());
        using var cancellation = new CancellationTokenSource();

        var written = await channel.WriteAsync(Request(answerOwed), cancellation.Token);

        Assert.Equal(1, store.AppendCalls);
        Assert.Same(store.Appended, written);
        Assert.NotEqual(Guid.Empty, written.Id);
        Assert.Equal("tenant-a", written.Tenant);
        Assert.Equal("principal-a", written.Recipient);
        Assert.Equal("decision", written.Tier);
        Assert.Equal("Approval required", written.Title);
        Assert.Equal("The full rendered message stays on the node.", written.RenderedContent);
        Assert.Equal("Record 17", written.SubjectDisplayName);
        Assert.Equal("/records/17", written.SubjectLink);
        Assert.Equal(answerOwed, written.AnswerOwed);
        Assert.Equal(WrittenAt, written.CreatedAt);
        Assert.Equal(InboxReadState.Unread, written.ReadState);
        Assert.Equal(cancellation.Token, store.AppendedToken);

        var second = await channel.WriteAsync(Request(answerOwed));
        Assert.NotEqual(Guid.Empty, second.Id);
        Assert.NotEqual(written.Id, second.Id);
        Assert.Equal(2, store.AppendCalls);
    }

    [Fact]
    public async Task Notification_delivery_ck_10_write_waits_for_commit_and_returns_the_stores_committed_entry()
    {
        var completion = new TaskCompletionSource<InboxEntry>(TaskCreationOptions.RunContinuationsAsynchronously);
        var store = new RecordingInboxStore { AppendResult = _ => completion.Task };
        var channel = new InboxChannel(store, new FixedClock());

        var writing = channel.WriteAsync(Request(answerOwed: true));

        Assert.Equal(1, store.AppendCalls);
        Assert.False(writing.IsCompleted);
        var committed = new InboxEntry(Guid.Parse("00000000-0000-0000-0000-000000000017"),
            "tenant-a", "principal-a", "decision", "Committed title", "Committed rendered content",
            "Record 17", "/records/17", true, WrittenAt, InboxReadState.Unread);
        completion.SetResult(committed);

        Assert.Same(committed, await writing);
    }

    [Fact]
    public async Task Notification_delivery_ck_10_persistence_failure_propagates_without_returning_an_uncommitted_entry()
    {
        var refusal = new InvalidOperationException("Store commit refused");
        var store = new RecordingInboxStore { AppendResult = _ => Task.FromException<InboxEntry>(refusal) };
        var channel = new InboxChannel(store, new FixedClock());

        var exception = await Assert.ThrowsAsync<InvalidOperationException>(() => channel.WriteAsync(Request(answerOwed: true)));

        Assert.Same(refusal, exception);
        Assert.Equal(1, store.AppendCalls);
    }

    [Fact]
    public async Task Notification_delivery_ck_10_cancelled_write_never_persists_an_entry()
    {
        var store = new InMemoryInboxStore();
        var channel = new InboxChannel(store, new FixedClock());
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();

        var exception = await Assert.ThrowsAsync<OperationCanceledException>(() => channel.WriteAsync(Request(false), cancellation.Token));

        Assert.Equal(cancellation.Token, exception.CancellationToken);
        Assert.Empty(await store.ListAsync("tenant-a", "principal-a"));
    }

    private static WriteInboxEntry Request(bool answerOwed) => new("tenant-a", "principal-a", "decision",
        "Approval required", "The full rendered message stays on the node.", "Record 17", "/records/17", answerOwed);

    private sealed class FixedClock : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => WrittenAt;
    }

    private sealed class RecordingInboxStore : IInboxStore
    {
        public int AppendCalls { get; private set; }
        public InboxEntry? Appended { get; private set; }
        public CancellationToken AppendedToken { get; private set; }
        public Func<InboxEntry, Task<InboxEntry>> AppendResult { get; init; } = Task.FromResult;

        public Task<InboxEntry> AppendAsync(InboxEntry entry, CancellationToken cancellationToken = default)
        {
            AppendCalls++;
            Appended = entry;
            AppendedToken = cancellationToken;
            return AppendResult(entry);
        }

        public Task<IReadOnlyList<InboxEntry>> ListAsync(string tenant, string recipient, CancellationToken cancellationToken = default) =>
            throw new NotSupportedException();
        public Task<int> UnreadCountAsync(string tenant, string recipient, CancellationToken cancellationToken = default) =>
            throw new NotSupportedException();
        public Task MarkReadAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default) =>
            throw new NotSupportedException();
        public Task MarkAllReadAsync(string tenant, string recipient, CancellationToken cancellationToken = default) =>
            throw new NotSupportedException();
    }
}
